import {constellationNodes,doctrineNodeState,syncDoctrines} from './constellation-model.js';
import {resonancePoints} from './resonance-link.js';
import {RARE_MAKO,ownsRelic,discoveryGrowth} from './wayglass-model.js?v=5.11.0';
import {CREW} from './mako.js?v=5.16.0';
export const PATHS=[{name:'Vitality',stat:'maxHp',value:18,color:'#80dfb4',icon:'♥'},{name:'Focus',stat:'maxMp',value:4,color:'#7ccbf0',icon:'◈'},{name:'Strength',stat:'power',value:3,color:'#efa477',icon:'◆'},{name:'Sorcery',stat:'magic',value:3,color:'#c4a1ef',icon:'✦'},{name:'Tempo',stat:'speed',value:.025,color:'#e4d48d',icon:'»'},{name:'Personal arts',stat:'skill',color:'#f4a9c4',icon:'✧'},{name:'Crystal mastery',stat:'ap',value:18,color:'#82e0da',icon:'⬡'}];
PATHS.push({name:'Rare Mako',stat:'mako',color:'#f0d59a',icon:'◈'});
export function nodesFor(id){return [{id:'origin',name:CREW[id].name,branch:-1,x:800,y:800,cost:0,requires:null},...PATHS.slice(0,7).flatMap((p,b)=>Array.from({length:8},(_,i)=>{const angle=-Math.PI/2+b*Math.PI*2/7+Math.sin(i*.85)*.07,r=115+i*82;return {id:b+':'+i,branch:b,step:i,x:800+Math.cos(angle)*r,y:800+Math.sin(angle)*r,requires:i?b+':'+(i-1):'origin',cost:i<3?1:i<6?2:3,name:p.name+' '+(i+1),stat:p.stat,value:p.value};})),...constellationNodes(),...RARE_MAKO.map((r,i)=>({id:'mako:'+r.id,name:r.name+' attunement',branch:7,step:i,x:620+i*180,y:690-i%2*110,requires:r.prerequisite,cost:r.cost,stat:'mako',makoId:r.id,core:r.core}))];}
export function earnedPoints(s,id){return Math.max(0,2*(s.heroes[id].level-1)+Math.floor((s.bosses?.length||0)/2)+(s.chapter>=2?1:0)+resonancePoints(s)+Math.max(0,Math.min(24,Number(s.physicalLore?.growthPoints?.[id])||0)));}
export function ownedNodes(s,id){return new Set(['origin',...(s.skillGrid?.[id]||[])]);}
export function availablePoints(s,id){const owned=ownedNodes(s,id);return earnedPoints(s,id)-nodesFor(id).reduce((n,v)=>n+(owned.has(v.id)&&!(s.crewSetup?.freeNodes?.[id]||[]).includes(v.id)?v.cost:0),0);}
export function nodeState(s,id,node){const own=ownedNodes(s,id);if(node.doctrine)return doctrineNodeState(s,id,node,availablePoints(s,id));if(own.has(node.id))return 'learned';if(node.stat==='mako'&&!ownsRelic(s,node.makoId))return 'undiscovered';if(node.stat==='mako'&&!(s.cores||[]).includes(node.core))return 'pattern';if(!own.has(node.requires))return 'locked';if(['skill','ap'].includes(node.stat)&&s.chapter<2)return 'story';return availablePoints(s,id)>=node.cost?'available':'unaffordable';}
export function unlockNode(s,id,nodeId){const node=nodesFor(id).find(n=>n.id===nodeId);if(node?.doctrine&&s.mode==='battle')return false;if(!s.recruited.includes(id)||!node||nodeState(s,id,node)!=='available')return false;const h=s.heroes[id];s.skillGrid??={};(s.skillGrid[id]??=[]).push(node.id);if(node.doctrine){syncDoctrines(s,id);return true;}if(node.stat==='mako'){return true;}else if(node.stat==='skill')h.learned|=1<<(7-node.step);else if(node.stat==='ap'){h.ap??={};const core=CREW[id].affinity;h.ap[core]=(h.ap[core]||0)+node.value;}else{h.gridBonuses??={};h.gridBonuses[node.stat]=(h.gridBonuses[node.stat]||0)+node.value;h[node.stat]=(h[node.stat]||0)+node.value;if(node.stat==='maxHp')h.hp+=node.value;if(node.stat==='maxMp')h.mp+=node.value;}return true;}
